using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using BepInEx.Configuration;
using UnityEngine;
using AssistantChat;
namespace LocalSpt5Esp;
internal static partial class RaidChat {
 sealed record Line(string Text,float Time,Color Color);
 static readonly List<Line> lines=new();static readonly List<string> history=new();static readonly ConcurrentQueue<Action> completions=new();static readonly MenuInputGate gate=new();
 static AssistantChatClient? client;static ConfigEntry<KeyCode>? hotkey;static ConfigEntry<bool>? enabled;static string session="",input="",draft="",reply="";static int frame=-1,openedFrame,index,caret=-1,completionIndex;static bool focus,oldVisible;static CursorLockMode oldLock;static GUIStyle? style,field;static Vector2 scroll;static string[] candidates=Array.Empty<string>();static string completionInput="",completionSuffix="";static float retryAt;
 internal static bool Open=>gate.Open;internal static bool InputBlocked=>gate.Blocked;
 internal static void Initialize(){hotkey=FeatureConfig.Bind("64. 聊天与命令","Chat key","聊天按键",KeyCode.T,"打开聊天时拦截游戏输入；可修改按键以避开原生 T 战术设备快捷键。");enabled=FeatureConfig.Bind("64. 聊天与命令","Encrypted chat","连接加密聊天",true,"需要服务端聊天组件和双方核验指纹。关闭后仍可使用本地命令。");}
 static string Session(){try{return SPTushonka.Common.Http.RequestHandler.SessionId??"";}catch{return "";}}
 internal static void CaptureInput(){if(frame==Time.frameCount)return;frame=Time.frameCount;gate.Tick(frame,Input.GetMouseButton(0)||Input.GetMouseButton(1));if(hotkey==null||!Application.isFocused)return;if(!Open){if(RaidClock.Active&&!Cursor.visible&&!InterfaceMenu.Open&&!WorldEditor.ModalOpen&&!FloatingStatus.Capturing&&(Input.GetKeyDown(hotkey.Value)||Input.GetKeyDown(KeyCode.Slash))){SetOpen(true);input=Input.GetKeyDown(KeyCode.Slash)?"/":"";focus=true;caret=input.Length;}}else if(Input.GetKeyDown(KeyCode.Escape))SetOpen(false);}
 static void SetOpen(bool value){if(value==Open)return;if(value){WorldEditor.Suspend();oldLock=Cursor.lockState;oldVisible=Cursor.visible;gate.SetOpen(true,Time.frameCount);openedFrame=Time.frameCount;historyIndexReset();try{Comfort.Common.Singleton<EFT.GameWorld>.Instance?.MainPlayer?.HandsController?.TryCast<EFT.Player.FirearmController>()?.SetTriggerPressed(false);}catch{}}else{gate.SetOpen(false,Time.frameCount);Cursor.lockState=oldLock;Cursor.visible=oldVisible;input="";candidates=Array.Empty<string>();Input.imeCompositionMode=IMECompositionMode.Auto;}KeepCursor();}
 static void historyIndexReset(){index=history.Count;draft="";}
 internal static void KeepCursor(){if(Open){Cursor.lockState=CursorLockMode.None;Cursor.visible=true;}}
 internal static void Tick(){CaptureInput();RaidCommands.Tick();while(completions.TryDequeue(out var action))action();string key=Session();if(key!=session){client?.Dispose();client=null;session=key;reply="";lines.Clear();history.Clear();retryAt=0;RaidCommands.Reset();}if(enabled?.Value!=true){client?.Dispose();client=null;return;}if(client==null&&key.Length>0&&Time.unscaledTime>=retryAt){retryAt=Time.unscaledTime+60;try{client=new(key);}catch{Output("无法读取聊天身份。请检查 Windows 用户和 chat 目录权限；没有自动重置密钥。",true);}}if(client==null)return;while(client.TryNotice(out var notice))Output(notice);while(client.TryReceive(out var packet)){var p=client.Peers.FirstOrDefault(p=>p.Profile==packet.Peer);string name=p?.Name??packet.Peer;var msg=packet.Message;if(msg.Kind is not ("chat" or "whisper" or "me"))continue;if(msg.Text.Length>2000)continue;Output(msg.Kind=="me"?"* "+name+" "+Clean(msg.Text):msg.Kind=="whisper"?"[私信] "+name+": "+Clean(msg.Text):name+": "+Clean(msg.Text));if(msg.Kind=="whisper")reply=packet.Peer;}}
 static string Clean(string text)=>new(text.Select(c=>char.IsControl(c)&&c!='\n'?' ':c).ToArray());
 internal static void Output(string value,bool error=false){foreach(string line in Clean(value).Split('\n')){lines.Add(new(line,Time.unscaledTime,error?new Color(1,.55f,.5f):Color.white));if(lines.Count>200)lines.RemoveAt(0);}scroll.y=float.MaxValue;}
 static void Submit(){string value=input.Trim();if(value.Length==0){SetOpen(false);return;}if(history.Count==0||history[^1]!=value)history.Add(value);if(history.Count>100)history.RemoveAt(0);SetOpen(false);try{if(value.StartsWith('/')&&!value.StartsWith("//",StringComparison.Ordinal)){Command(value[1..]);return;}Send(value.StartsWith("//",StringComparison.Ordinal)?value[1..]:value,null,"chat");}catch(Exception e){Output(e.Message,true);}}
 static void Send(string text,string? to,string kind){if(client==null)throw new ArgumentException("聊天未连接。安装服务端组件后使用 /chat reconnect。");var current=client;_ = SendAsync(current,text,to,kind);}
 static async Task SendAsync(AssistantChatClient current,string text,string? to,string kind){try{await current.Send(text,to,kind);completions.Enqueue(()=>Output(to==null?"<我> "+text:"[私信 → "+to+"] "+text));}catch(Exception e){completions.Enqueue(()=>Output("发送结果未确认："+e.Message+"。不会自动重发。",true));}}
 static void Command(string value){var words=ChatCommandSyntax.Tokens(value);if(words.Length==0){Output(RaidCommands.Help());return;}string name=words[0].ToLowerInvariant();var args=words.Skip(1).ToArray();switch(name){
  case "help":Output(RaidCommands.Help(args.FirstOrDefault()));break;
  case "identity":if(client==null)throw new ArgumentException("聊天未连接。");if(args.Length==3&&args[0]=="verify")Output(client.Verify(args[1],args[2]));else if(args.Length==0){Output("我的档案 ID："+session+"\n我的指纹："+client.Fingerprint);foreach(var p in client.Peers)Output(client.Describe(p));}else throw new ArgumentException("/identity verify <档案 ID 或唯一名称> <通过其他可信渠道核对的指纹>");break;
  case "list":Output("当前在线：");if(client!=null)foreach(var p in client.Peers)Output(p.Name+"  "+p.Profile);if(RaidClock.Active)RaidCommands.Execute("list",args);break;
  case "msg":case "tell":case "w":if(args.Length<2)throw new ArgumentException("/msg <玩家> <消息>");Send(string.Join(" ",args.Skip(1)),args[0],"whisper");break;
  case "reply":case "r":if(reply.Length==0||args.Length==0)throw new ArgumentException("没有最近私信，或消息为空。");Send(string.Join(" ",args),reply,"whisper");break;
  case "me":Send(string.Join(" ",args),null,"me");break;
  case "teammsg":case "tm":throw new ArgumentException("当前单人版没有服务端验证的队伍路由，不能把全服频道冒充队伍频道。");
  case "say":throw new ArgumentException("当前版本没有经过验证的公告签名，普通聊天不能冒充服务器公告。");
  case "clearhistory":lines.Clear();history.Clear();reply="";break;
  case "chat":if(args.Length==1&&args[0]=="reconnect"){client?.Dispose();client=null;retryAt=0;Output("正在使用新会话重新连接。");}else throw new ArgumentException("/chat reconnect");break;
  case "permission":if(args.Length>1||args.Length==1&&args[0]!="list")throw new ArgumentException("/permission [list] · 当前仅支持只读查询。");Output("本地命令：本机单人战局完全控制；远程操作：禁用。\n聊天中继权限："+string.Join(", ",client?.Permissions??Array.Empty<string>()));break;
  default:RaidCommands.Execute(name,args);break;
 }}
 static TextEditor Editor()=>GUIUtility.GetStateObject(Il2CppInterop.Runtime.Il2CppType.Of<TextEditor>(),GUIUtility.keyboardControl).Cast<TextEditor>();
 static void Keys(){var e=Event.current;if(e.type!=EventType.KeyDown)return;if(Time.frameCount==openedFrame){e.Use();return;}if(GUI.GetNameOfFocusedControl()!="AssistantChatInput")return;if(e.keyCode is KeyCode.Return or KeyCode.KeypadEnter){if(!string.IsNullOrEmpty(Input.compositionString))return;Submit();e.Use();return;}if(e.keyCode==KeyCode.Escape){SetOpen(false);e.Use();return;}if(e.keyCode is KeyCode.UpArrow or KeyCode.DownArrow){if(index==history.Count)draft=input;index=Math.Clamp(index+(e.keyCode==KeyCode.UpArrow?-1:1),0,history.Count);input=index<history.Count?history[index]:draft;caret=input.Length;focus=true;e.Use();return;}if(e.keyCode==KeyCode.Tab){var editor=Editor();int pos=Math.Clamp(editor.cursorIndex,0,input.Length);if(completionInput!=input||candidates.Length==0){completionSuffix=input[pos..];candidates=RaidCommands.Complete(input[..pos],client?.Peers??Array.Empty<ChatPeer>());completionIndex=e.shift?candidates.Length-1:0;}else if(candidates.Length>0)completionIndex=(completionIndex+(e.shift?-1:1)+candidates.Length)%candidates.Length;if(candidates.Length>0){input=candidates[completionIndex]+completionSuffix;caret=candidates[completionIndex].Length;completionInput=input;focus=true;}e.Use();}}
 internal static void Draw(){if(InterfaceMenu.Open||WorldEditor.ModalOpen)return;int oldDepth=GUI.depth;try{GUI.depth=-9000;style??=new GUIStyle(GUI.skin.label){fontSize=15,wordWrap=true,richText=false};field??=new GUIStyle(GUI.skin.textField){fontSize=16,richText=false};float width=Math.Min(900,Screen.width-32),height=Math.Min(320,Screen.height*.42f),x=16,bottom=Screen.height-24;var visible=Open?lines.ToArray():lines.Where(l=>Time.unscaledTime-l.Time<10).TakeLast(6).ToArray();if(Open){KeepCursor();InterfaceMenu.Surface(new Rect(x,bottom-height,width,height),new Color(.02f,.025f,.04f,.9f),5);var viewport=new Rect(x+8,bottom-height+8,width-16,height-58);float content=0;foreach(var line in visible)content+=Math.Max(22,style.CalcHeight(new GUIContent(line.Text),width-40));scroll=GUI.BeginScrollView(viewport,scroll,new Rect(0,0,width-38,Math.Max(viewport.height,content)));float y=0;foreach(var line in visible){float h=Math.Max(22,style.CalcHeight(new GUIContent(line.Text),width-40));style.normal.textColor=line.Color;GUI.Label(new Rect(0,y,width-40,h),line.Text,style);y+=h;}GUI.EndScrollView();Keys();if(!Open)return;GUI.SetNextControlName("AssistantChatInput");input=GUI.TextField(new Rect(x+8,bottom-40,width-16,30),input,2048,field);if(focus){GUI.FocusControl("AssistantChatInput");var editor=Editor();editor.text=input;editor.cursorIndex=editor.selectIndex=caret<0?input.Length:caret;focus=false;caret=-1;}Input.imeCompositionMode=IMECompositionMode.On;Input.compositionCursorPos=new Vector2(x+16,bottom-40);if(candidates.Length>1)InterfaceMenu.Label(new Rect(x,bottom-height-26,width,24),string.Join("  ",candidates.Take(4)),Color.cyan,12,translate:false);}else{float y=bottom-visible.Sum(l=>Math.Min(80,Math.Max(22,style.CalcHeight(new GUIContent(l.Text),width-20))));foreach(var line in visible){float h=Math.Min(80,Math.Max(22,style.CalcHeight(new GUIContent(line.Text),width-20))),alpha=Math.Clamp((10-(Time.unscaledTime-line.Time))/2,0,1);InterfaceMenu.Surface(new Rect(x,y,width,h),new Color(0,0,0,.45f*alpha),1);style.normal.textColor=new Color(line.Color.r,line.Color.g,line.Color.b,alpha);GUI.Label(new Rect(x+8,y,width-16,h),line.Text,style);y+=h;}}}finally{GUI.depth=oldDepth;}}
 internal static void Reset(){client?.Dispose();client=null;SetOpen(false);gate.Reset();session="";frame=-1;lines.Clear();history.Clear();while(completions.TryDequeue(out _)){}RaidCommands.Reset();}
}
